 1→import { useState } from "react";
 2→import AppHeader from "@/components/AppHeader";
 3→import AdminSidebar, { type AdminSection } from "@/components/admin/AdminSidebar";
 4→import AdminErrorBoundary from "@/components/admin/AdminErrorBoundary";
 5→import DashboardTab from "@/components/admin/DashboardTab";
 6→import UsersTab from "@/components/admin/UsersTab";
 7→import BillingTab from "@/components/admin/BillingTab";
 8→import PlatformSettingsTab from "@/components/admin/PlatformSettingsTab";
 9→import EmailSettingsTab from "@/components/admin/EmailSettingsTab";
10→import AIPromptsTab from "@/components/admin/AIPromptsTab";
11→import IntegrationsTab from "@/components/admin/IntegrationsTab";
12→import UsageLogsTab from "@/components/admin/UsageLogsTab";
13→import AuditLogsTab from "@/components/admin/AuditLogsTab";
14→import SystemErrorLogsTab from "@/components/admin/SystemErrorLogsTab";
15→import SeoTab from "@/components/admin/SeoTab";
16→
17→const sectionComponents: Record<AdminSection, React.ComponentType> = {
18→  dashboard: DashboardTab,
19→  users: UsersTab,
20→  billing: BillingTab,
21→  platform_settings: PlatformSettingsTab,
22→  email_settings: EmailSettingsTab,
23→  ai_prompts: AIPromptsTab,
24→  seo: SeoTab,
25→  integrations: IntegrationsTab,
26→  logs: UsageLogsTab,
27→  audit_logs: AuditLogsTab,
28→  system_errors: SystemErrorLogsTab,
29→};
30→
31→const Admin = () => {
32→  const [section, setSection] = useState<AdminSection>("dashboard");
33→  const ActiveComponent = sectionComponents[section];
34→
35→  return (
36→    <div className="min-h-screen bg-background">
37→      <AppHeader />
38→      <div className="flex">
39→        <AdminSidebar active={section} onSelect={setSection} />
40→        <main className="flex-1 p-6 overflow-auto">
41→          <AdminErrorBoundary key={section}>
42→            <ActiveComponent />
43→          </AdminErrorBoundary>
44→        </main>
45→      </div>
46→    </div>
47→  );
48→};
49→
50→export default Admin;
51→

 1→import {
 2→  LayoutDashboard, Users, CreditCard, Settings, Plug, ScrollText, Mail, BrainCircuit,
 3→  Eye, UserCog, Wrench, Server, ClipboardList, Search, AlertTriangle,
 4→} from "lucide-react";
 5→import { cn } from "@/lib/utils";
 6→
 7→const sectionGroups = [
 8→  {
 9→    label: "Overview",
10→    icon: Eye,
11→    items: [
12→      { key: "dashboard", label: "Dashboard", icon: LayoutDashboard },
13→    ],
14→  },
15→  {
16→    label: "Users & Billing",
17→    icon: UserCog,
18→    items: [
19→      { key: "users", label: "Users", icon: Users },
20→      { key: "billing", label: "Billing & Plans", icon: CreditCard },
21→    ],
22→  },
23→  {
24→    label: "Configuration",
25→    icon: Wrench,
26→    items: [
27→      { key: "platform_settings", label: "Platform Settings", icon: Settings },
28→      { key: "email_settings", label: "Email Settings", icon: Mail },
29→      { key: "ai_prompts", label: "AI Prompts", icon: BrainCircuit },
30→      { key: "seo", label: "SEO", icon: Search },
31→    ],
32→  },
33→  {
34→    label: "System",
35→    icon: Server,
36→    items: [
37→      { key: "integrations", label: "Integrations", icon: Plug },
38→      { key: "logs", label: "Usage Logs", icon: ScrollText },
39→      { key: "audit_logs", label: "Audit Logs", icon: ClipboardList },
40→      { key: "system_errors", label: "System Errors", icon: AlertTriangle },
41→    ],
42→  },
43→] as const;
44→
45→type SectionItem = (typeof sectionGroups)[number]["items"][number];
46→export type AdminSection = SectionItem["key"];
47→
48→interface AdminSidebarProps {
49→  active: AdminSection;
50→  onSelect: (section: AdminSection) => void;
51→}
52→
53→const AdminSidebar = ({ active, onSelect }: AdminSidebarProps) => {
54→  return (
55→    <aside className="w-56 shrink-0 border-r border-border bg-card min-h-[calc(100vh-3.5rem)]">
56→      <nav className="flex flex-col gap-1 p-3">
57→        {sectionGroups.map((group, gi) => {
58→          const GroupIcon = group.icon;
59→          return (
60→            <div key={group.label} className="animate-in fade-in slide-in-from-left-2 duration-300" style={{ animationDelay: `${gi * 75}ms`, animationFillMode: "backwards" }}>
61→              {gi > 0 && <div className="my-2 h-px bg-border" />}
62→              <span className="group/header flex items-center gap-1.5 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
63→                <GroupIcon className="h-3 w-3 shrink-0 opacity-60 transition-transform duration-200 group-hover/header:scale-110" />
64→                {group.label}
65→              </span>
66→              {group.items.map(({ key, label, icon: Icon }) => (
67→                <button
68→                  key={key}
69→                  onClick={() => onSelect(key)}
70→                  className={cn(
71→                    "flex items-center gap-2.5 rounded-md px-3 py-2 text-sm font-medium transition-all duration-200 text-left w-full",
72→                    active === key
73→                      ? "bg-primary/10 text-primary"
74→                      : "text-muted-foreground hover:bg-accent hover:text-accent-foreground hover:translate-x-0.5"
75→                  )}
76→                >
77→                  <Icon className="h-4 w-4 shrink-0 transition-transform duration-200" />
78→                  {label}
79→                </button>
80→              ))}
81→            </div>
82→          );
83→        })}
84→      </nav>
85→    </aside>
86→  );
87→};
88→
89→export default AdminSidebar;
