  1→import { useState } from "react";
  2→import { useQuery, useQueryClient } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  5→import { Button } from "@/components/ui/button";
  6→import { Calendar } from "@/components/ui/calendar";
  7→import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
  8→import { Badge } from "@/components/ui/badge";
  9→import {
 10→  Users, Briefcase, FileText, Coins, DollarSign, TrendingUp, UserCheck, BarChart3,
 11→  RefreshCw, CalendarIcon, Mail, Inbox, ArrowRight,
 12→} from "lucide-react";
 13→import { Skeleton } from "@/components/ui/skeleton";
 14→import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, LineChart, Line } from "recharts";
 15→import { format, subDays } from "date-fns";
 16→import { cn } from "@/lib/utils";
 17→import type { DateRange } from "react-day-picker";
 18→
 19→interface StatsData {
 20→  total_users: number;
 21→  total_jobs: number;
 22→  total_resumes: number;
 23→  total_credits_used: number;
 24→  total_revenue: number;
 25→  mrr_30d: number;
 26→  conversion_rate: number;
 27→  active_users_7d: number;
 28→  active_users_30d: number;
 29→  avg_resumes_per_job: number;
 30→  resumes_today: number;
 31→  resumes_week: number;
 32→  resumes_month: number;
 33→  daily_chart: { date: string; credits: number; jobs: number; signups: number; revenue: number }[];
 34→}
 35→
 36→const PRESETS = [
 37→  { label: "7 days", days: 7 },
 38→  { label: "30 days", days: 30 },
 39→  { label: "90 days", days: 90 },
 40→  { label: "1 year", days: 365 },
 41→] as const;
 42→
 43→const DashboardTab = () => {
 44→  const qc = useQueryClient();
 45→  const [dateRange, setDateRange] = useState<DateRange | undefined>({
 46→    from: subDays(new Date(), 30),
 47→    to: new Date(),
 48→  });
 49→  const [activePreset, setActivePreset] = useState<number>(30);
 50→
 51→  const fromISO = dateRange?.from?.toISOString().slice(0, 10);
 52→  const toISO = dateRange?.to?.toISOString().slice(0, 10);
 53→
 54→  const { data: stats, isLoading, isFetching } = useQuery({
 55→    queryKey: ["admin_stats", fromISO, toISO],
 56→    queryFn: async () => {
 57→      const { data, error } = await supabase.functions.invoke("admin-stats", {
 58→        body: { from: fromISO, to: toISO },
 59→      });
 60→      if (error) throw error;
 61→      return data as StatsData;
 62→    },
 63→  });
 64→
 65→  const { data: emailConfig } = useQuery({
 66→    queryKey: ["admin_email_config"],
 67→    queryFn: async () => {
 68→      const { data, error } = await supabase.from("platform_config").select("email_ingestion_enabled").limit(1).single();
 69→      if (error) throw error;
 70→      return data;
 71→    },
 72→    staleTime: 5 * 60 * 1000,
 73→  });
 74→
 75→  const selectPreset = (days: number) => {
 76→    setActivePreset(days);
 77→    setDateRange({ from: subDays(new Date(), days), to: new Date() });
 78→  };
 79→
 80→  const handleRangeSelect = (range: DateRange | undefined) => {
 81→    setDateRange(range);
 82→    setActivePreset(0); // clear preset when custom selected
 83→  };
 84→
 85→  const rangeDays = dateRange?.from && dateRange?.to
 86→    ? Math.ceil((dateRange.to.getTime() - dateRange.from.getTime()) / (1000 * 60 * 60 * 24))
 87→    : 30;
 88→  const rangeLabel = activePreset
 89→    ? PRESETS.find(p => p.days === activePreset)?.label ?? `${rangeDays}d`
 90→    : dateRange?.from && dateRange?.to
 91→      ? `${format(dateRange.from, "MMM d")} – ${format(dateRange.to, "MMM d, yyyy")}`
 92→      : "30 days";
 93→
 94→  const cards = [
 95→    { label: "Total Users", value: stats?.total_users, icon: Users, color: "text-blue-500" },
 96→    { label: "Active Users (7d)", value: stats?.active_users_7d, icon: UserCheck, color: "text-emerald-500" },
 97→    { label: "Total Jobs", value: stats?.total_jobs, icon: Briefcase, color: "text-primary" },
 98→    { label: "Resumes Processed", value: stats?.total_resumes, icon: FileText, color: "text-amber-500", subtitle: `Today: ${stats?.resumes_today ?? 0} · Week: ${stats?.resumes_week ?? 0}` },
 99→    { label: "Credits Consumed", value: stats?.total_credits_used, icon: Coins, color: "text-purple-500" },
100→    { label: "Total Revenue", value: stats?.total_revenue != null ? `$${(stats.total_revenue / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : undefined, icon: DollarSign, color: "text-green-500", subtitle: `Period: $${((stats?.mrr_30d ?? 0) / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` },
101→    { label: "Conversion Rate", value: stats?.conversion_rate != null ? `${stats.conversion_rate}%` : undefined, icon: TrendingUp, color: "text-rose-500" },
102→    { label: "Avg Resumes/Job", value: stats?.avg_resumes_per_job, icon: BarChart3, color: "text-cyan-500" },
103→  ];
104→
105→  const chartInterval = rangeDays > 90 ? Math.floor(rangeDays / 15) : rangeDays > 30 ? 7 : 4;
106→
107→  const chartData = stats?.daily_chart?.map((d) => ({
108→    ...d,
109→    label: new Date(d.date).toLocaleDateString("en-US", { month: "short", day: "numeric" }),
110→    revenue_dollars: d.revenue / 100,
111→  })) ?? [];
112→
113→  const tooltipStyle = { borderRadius: 8, border: "1px solid hsl(var(--border))", background: "hsl(var(--card))" };
114→
115→  return (
116→    <div className="space-y-6">
117→      <div className="flex items-center justify-between flex-wrap gap-3">
118→        <h2 className="text-xl font-semibold">Dashboard Overview</h2>
119→        <div className="flex items-center gap-2 flex-wrap">
120→          {/* Preset buttons */}
121→          {PRESETS.map(({ label, days }) => (
122→            <Button
123→              key={days}
124→              variant={activePreset === days ? "default" : "outline"}
125→              size="sm"
126→              className="h-8 text-xs"
127→              onClick={() => selectPreset(days)}
128→            >
129→              {label}
130→            </Button>
131→          ))}
132→
133→          {/* Custom date range picker */}
134→          <Popover>
135→            <PopoverTrigger asChild>
136→              <Button
137→                variant={activePreset === 0 ? "default" : "outline"}
138→                size="sm"
139→                className={cn("h-8 text-xs gap-1.5", activePreset === 0 && "font-medium")}
140→              >
141→                <CalendarIcon className="h-3.5 w-3.5" />
142→                {activePreset === 0 && dateRange?.from ? rangeLabel : "Custom"}
143→              </Button>
144→            </PopoverTrigger>
145→            <PopoverContent className="w-auto p-0" align="end">
146→              <Calendar
147→                mode="range"
148→                selected={dateRange}
149→                onSelect={handleRangeSelect}
150→                numberOfMonths={2}
151→                disabled={(date) => date > new Date()}
152→                initialFocus
153→                className={cn("p-3 pointer-events-auto")}
154→              />
155→            </PopoverContent>
156→          </Popover>
157→
158→          <Button
159→            variant="outline"
160→            size="sm"
161→            className="h-8"
162→            onClick={() => qc.invalidateQueries({ queryKey: ["admin_stats", fromISO, toISO] })}
163→            disabled={isFetching}
164→          >
165→            <RefreshCw className={`h-3.5 w-3.5 ${isFetching ? "animate-spin" : ""}`} />
166→          </Button>
167→        </div>
168→      </div>
169→
170→      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
171→        {cards.map(({ label, value, icon: Icon, color, subtitle }) => (
172→          <Card key={label}>
173→            <CardHeader className="flex flex-row items-center justify-between pb-2">
174→              <CardTitle className="text-sm font-medium text-muted-foreground">{label}</CardTitle>
175→              <Icon className={`h-4 w-4 ${color}`} />
176→            </CardHeader>
177→            <CardContent>
178→              {isLoading ? (
179→                <Skeleton className="h-8 w-20" />
180→              ) : (
181→                <>
182→                  <div className="text-2xl font-bold">
183→                    {typeof value === "string" ? value : (value?.toLocaleString() ?? 0)}
184→                  </div>
185→                  {subtitle && <p className="text-xs text-muted-foreground mt-1">{subtitle}</p>}
186→                </>
187→              )}
188→            </CardContent>
189→          </Card>
190→        ))}
191→      </div>
192→
193→      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
194→        <Card>
195→          <CardHeader className="pb-2">
196→            <CardTitle className="text-sm font-medium text-muted-foreground">Credits Usage ({rangeLabel})</CardTitle>
197→          </CardHeader>
198→          <CardContent>
199→            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
200→              <ResponsiveContainer width="100%" height={220}>
201→                <AreaChart data={chartData}>
202→                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
203→                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
204→                  <YAxis tick={{ fontSize: 11 }} className="text-muted-foreground" />
205→                  <Tooltip contentStyle={tooltipStyle} />
206→                  <Area type="monotone" dataKey="credits" stroke="hsl(var(--primary))" fill="hsl(var(--primary) / 0.15)" strokeWidth={2} />
207→                </AreaChart>
208→              </ResponsiveContainer>
209→            )}
210→          </CardContent>
211→        </Card>
212→
213→        <Card>
214→          <CardHeader className="pb-2">
215→            <CardTitle className="text-sm font-medium text-muted-foreground">Revenue ({rangeLabel})</CardTitle>
216→          </CardHeader>
217→          <CardContent>
218→            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
219→              <ResponsiveContainer width="100%" height={220}>
220→                <AreaChart data={chartData}>
221→                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
222→                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
223→                  <YAxis tick={{ fontSize: 11 }} className="text-muted-foreground" />
224→                  <Tooltip contentStyle={tooltipStyle} formatter={(val: number) => [`$${val.toFixed(2)}`, "Revenue"]} />
225→                  <Area type="monotone" dataKey="revenue_dollars" stroke="hsl(142 71% 45%)" fill="hsl(142 71% 45% / 0.15)" strokeWidth={2} />
226→                </AreaChart>
227→              </ResponsiveContainer>
228→            )}
229→          </CardContent>
230→        </Card>
231→
232→        <Card>
233→          <CardHeader className="pb-2">
234→            <CardTitle className="text-sm font-medium text-muted-foreground">Jobs Created ({rangeLabel})</CardTitle>
235→          </CardHeader>
236→          <CardContent>
237→            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
238→              <ResponsiveContainer width="100%" height={220}>
239→                <BarChart data={chartData}>
240→                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
241→                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
242→                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} className="text-muted-foreground" />
243→                  <Tooltip contentStyle={tooltipStyle} />
244→                  <Bar dataKey="jobs" fill="hsl(var(--primary))" radius={[4, 4, 0, 0]} />
245→                </BarChart>
246→              </ResponsiveContainer>
247→            )}
248→          </CardContent>
249→        </Card>
250→
251→        <Card>
252→          <CardHeader className="pb-2">
253→            <CardTitle className="text-sm font-medium text-muted-foreground">User Signups ({rangeLabel})</CardTitle>
254→          </CardHeader>
255→          <CardContent>
256→            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
257→              <ResponsiveContainer width="100%" height={220}>
258→                <LineChart data={chartData}>
259→                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
260→                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
261→                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} className="text-muted-foreground" />
262→                  <Tooltip contentStyle={tooltipStyle} />
263→                  <Line type="monotone" dataKey="signups" stroke="hsl(var(--primary))" strokeWidth={2} dot={{ r: 3, fill: "hsl(var(--primary))" }} />
264→                </LineChart>
265→              </ResponsiveContainer>
266→            )}
267→          </CardContent>
268→        </Card>
269→      </div>
270→
271→      {/* Email Inbox Status Bar */}
272→      <div className="relative overflow-hidden rounded-xl border border-primary/20 bg-gradient-to-r from-primary/5 via-primary/10 to-primary/5 p-5">
273→        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full -translate-y-1/2 translate-x-1/2" />
274→        <div className="absolute bottom-0 left-0 w-24 h-24 bg-primary/5 rounded-full translate-y-1/2 -translate-x-1/2" />
275→        <div className="relative flex items-center justify-between flex-wrap gap-4">
276→          <div className="flex items-center gap-4">
277→            <div className="w-12 h-12 rounded-xl bg-primary/15 flex items-center justify-center">
278→              <Inbox className="h-6 w-6 text-primary" />
279→            </div>
280→            <div>
281→              <div className="flex items-center gap-2">
282→                <h3 className="text-sm font-semibold text-foreground">Email Ingestion</h3>
283→                <Badge variant={emailConfig?.email_ingestion_enabled ? "success" : "secondary"}>
284→                  {emailConfig?.email_ingestion_enabled ? "Active" : "Disabled"}
285→                </Badge>
286→              </div>
287→              <p className="text-xs text-muted-foreground mt-0.5">
288→                Users can forward resumes via email to auto-collect candidates into jobs.
289→              </p>
290→            </div>
291→          </div>
292→          <div className="flex items-center gap-3">
293→            <div className="text-right">
294→              <p className="text-lg font-bold text-foreground">{stats?.total_resumes ?? 0}</p>
295→              <p className="text-xs text-muted-foreground">Total resumes</p>
296→            </div>
297→            <div className="w-px h-8 bg-border" />
298→            <div className="text-right">
299→              <p className="text-lg font-bold text-foreground">{stats?.resumes_today ?? 0}</p>
300→              <p className="text-xs text-muted-foreground">Today</p>
301→            </div>
302→          </div>
303→        </div>
304→      </div>
305→
306→
307→    </div>
308→  );
309→};
310→
311→export default DashboardTab;
