 71→function HealthBanner({ health, loading, onVerify }: {
 72→  health: ResendHealth | null;
 73→  loading: boolean;
 74→  onVerify: () => void;
 75→}) {
 76→  if (loading) {
 77→    return (
 78→      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
 79→        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
