 81→      </div>
 82→    );
 83→  }
 84→
 85→  if (!health) return null;
 86→
 87→  const issues: { icon: React.ElementType; text: string; severity: "error" | "warning" }[] = [];
 88→
 89→  if (!health.keyValid) {
 90→    issues.push({ icon: XCircle, text: "API key is invalid or not configured", severity: "error" });
 91→  }
 92→  if (health.keyValid && !health.domainVerified) {
 93→    issues.push({
 94→      icon: AlertTriangle,
 95→      text: `Domain for "${health.fromEmail}" is not verified in Resend. Emails will fail.`,
 96→      severity: "warning",
 97→    });
 98→  }
 99→
100→  if (issues.length === 0 && health.keyValid) {
101→    return (
102→      <div className="rounded-lg border border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50 p-4 space-y-2">
103→        <div className="flex items-center justify-between">
